def test_containers_run_the_resolved_id_not_the_tag(fake_docker: list[tuple[str, ...]]) -> None:
    """Tags move — the reaper of a *concurrent* run sweeps `:e2e-*` by name. Running by id
    means a tag that vanishes mid-run cannot change what this container is."""
    ref = mc.resolve_image(RUNID, leg=mc.LEG_WORKING_TREE)

    assert ref.run_reference == "sha256:cafebabe"
    assert ref.run_reference != ref.reference


