def test_the_argv_is_the_one_the_real_client_spawns(fake_docker: list[tuple[str, ...]]) -> None:
    args = container(network="gwe2e-deadbeef-net", mounts=(("/host/backup", "/data"),)).run_args()

    assert args[:4] == ["docker", "run", "--rm", "-i"]
    assert args[-1] == "gramps-remote-mcp:e2e-deadbeef", "the image is the last word"
    assert "--label" in args and f"gramps-e2e={RUNID}" in args, "the reaper filters on the label"
    assert args[args.index("--network") + 1] == "gwe2e-deadbeef-net"
    assert args[args.index("-v") + 1] == "/host/backup:/data"
    assert args[args.index("-e") + 1] == "GRAMPS_BASE_URL=http://gwe2e-deadbeef-web:5000"


