def test_the_container_is_started_once_and_reused_across_calls(
    fake_docker: list[tuple[str, ...]], spawned: list[list[str]]
) -> None:
    """One container per test, not one per call — test_03 span up a fresh container for every
    seeded person, which is a bring-up and a JWT mint each time."""
    running = container()
    first = running.session
    for index in range(3):
        assert running.call("echo", {"n": index}).text == f'{{"n": {index}}}'

    assert running.session is first
    assert len(spawned) == 1, "asking for the session again must not spawn a second container"
    running.close()


def test_starting_registers_the_container_with_the_session_guard(
    fake_docker: list[tuple[str, ...]], spawned: list[list[str]]
) -> None:
    running = container()
    running.start()

    assert mc.STARTED == [running]
    running.close()


def test_close_deregisters_only_once_the_container_is_really_gone(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]], spawned: list[list[str]]
) -> None:
    monkeypatch.setattr(mc, "resource_exists", lambda kind, name: False)
    running = container()
    running.start()

    running.close()

    assert running.leftovers == []
    assert mc.STARTED == []


def test_a_container_that_survives_stays_visible_to_the_guard(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]], spawned: list[list[str]]
) -> None:
    """`--rm` is not a teardown: a wedged process leaves the container standing, and a
    teardown that never looks reports success either way."""
    monkeypatch.setattr(mc, "resource_exists", lambda kind, name: True)
    running = container()
    running.start()

    running.close()

    assert running.leftovers == [f"container:{running.name}"]
    assert mc.STARTED == [running]


def test_closing_twice_is_harmless(
    monkeypatch: pytest.MonkeyPatch, fake_docker: list[tuple[str, ...]], spawned: list[list[str]]
) -> None:
    """Fixtures tear down in the happy path and the session guard sweeps again afterwards."""
    monkeypatch.setattr(mc, "resource_exists", lambda kind, name: False)
    running = container()
    running.start()

    running.close()
    running.close()

    assert mc.STARTED == []
